CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', member_status text NOT NULL DEFAULT 'member', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.rbac_roles (key text PRIMARY KEY, name text NOT NULL, description text NOT NULL);
GRANT SELECT ON public.rbac_roles TO authenticated; GRANT ALL ON public.rbac_roles TO service_role;
ALTER TABLE public.rbac_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.rbac_permissions (key text PRIMARY KEY, module text NOT NULL CHECK(module IN ('RM','TREASURY','ADMIN')));
GRANT SELECT ON public.rbac_permissions TO authenticated; GRANT ALL ON public.rbac_permissions TO service_role;
ALTER TABLE public.rbac_permissions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.rbac_role_permissions (role_key text REFERENCES public.rbac_roles(key), permission_key text REFERENCES public.rbac_permissions(key), PRIMARY KEY(role_key,permission_key));
GRANT SELECT ON public.rbac_role_permissions TO authenticated; GRANT ALL ON public.rbac_role_permissions TO service_role;
ALTER TABLE public.rbac_role_permissions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.rbac_user_roles (user_id uuid NOT NULL, role_key text REFERENCES public.rbac_roles(key), PRIMARY KEY(user_id,role_key));
GRANT SELECT ON public.rbac_user_roles TO authenticated; GRANT ALL ON public.rbac_user_roles TO service_role;
ALTER TABLE public.rbac_user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.rbac_audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, target_id uuid, action text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.rbac_audit_logs TO authenticated; GRANT ALL ON public.rbac_audit_logs TO service_role;
ALTER TABLE public.rbac_audit_logs ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_permission(p_key text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.profiles p JOIN public.rbac_user_roles ur ON ur.user_id=p.id JOIN public.rbac_role_permissions rp ON rp.role_key=ur.role_key WHERE p.id=auth.uid() AND p.active AND rp.permission_key=p_key) $$;
REVOKE ALL ON FUNCTION public.has_permission(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_permission(text) TO authenticated;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_permission('manage_users'));
CREATE POLICY roles_read ON public.rbac_roles FOR SELECT TO authenticated USING(true);
CREATE POLICY permissions_read ON public.rbac_permissions FOR SELECT TO authenticated USING(true);
CREATE POLICY role_permissions_read ON public.rbac_role_permissions FOR SELECT TO authenticated USING(true);
CREATE POLICY own_roles_read ON public.rbac_user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_permission('manage_roles'));
CREATE POLICY admin_logs_read ON public.rbac_audit_logs FOR SELECT TO authenticated USING(public.has_permission('manage_users'));
CREATE FUNCTION public.create_church_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'full_name',NEW.raw_user_meta_data->>'name','')); RETURN NEW; END $$;
CREATE TRIGGER church_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_church_profile();
CREATE FUNCTION public.set_user_access(p_user uuid,p_role text,p_active boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old_roles jsonb; BEGIN IF NOT public.has_permission('manage_roles') OR NOT public.has_permission('manage_users') THEN RAISE EXCEPTION 'Access denied'; END IF; IF p_user=auth.uid() THEN RAISE EXCEPTION 'You cannot change your own access'; END IF; IF NOT EXISTS(SELECT 1 FROM public.rbac_roles WHERE key=p_role) THEN RAISE EXCEPTION 'Invalid role'; END IF; SELECT jsonb_agg(role_key) INTO old_roles FROM public.rbac_user_roles WHERE user_id=p_user; UPDATE public.profiles SET active=p_active WHERE id=p_user; IF NOT FOUND THEN RAISE EXCEPTION 'User not found'; END IF; DELETE FROM public.rbac_user_roles WHERE user_id=p_user; INSERT INTO public.rbac_user_roles VALUES(p_user,p_role); INSERT INTO public.rbac_audit_logs(actor_id,target_id,action,details) VALUES(auth.uid(),p_user,'access_updated',jsonb_build_object('old_roles',old_roles,'new_role',p_role,'active',p_active)); END $$;
REVOKE ALL ON FUNCTION public.set_user_access(uuid,text,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_user_access(uuid,text,boolean) TO authenticated;
CREATE TABLE public.treasury_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, currency text NOT NULL CHECK(currency IN ('TZS','KES')), opening_balance numeric(16,2) NOT NULL DEFAULT 0);
GRANT SELECT ON public.treasury_accounts TO authenticated; GRANT ALL ON public.treasury_accounts TO service_role;
ALTER TABLE public.treasury_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY accounts_read ON public.treasury_accounts FOR SELECT TO authenticated USING(public.has_permission('treasury_view'));
CREATE TABLE public.rm_contributions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, amount numeric(16,2) NOT NULL CHECK(amount>0), currency text NOT NULL DEFAULT 'TZS' CHECK(currency IN ('TZS','KES')), contributor text NOT NULL, reference text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed','failed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.rm_contributions TO authenticated; GRANT ALL ON public.rm_contributions TO service_role;
ALTER TABLE public.rm_contributions ENABLE ROW LEVEL SECURITY;
CREATE POLICY contribution_read ON public.rm_contributions FOR SELECT TO authenticated USING((user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND active)) OR public.has_permission('rm_view'));
CREATE TABLE public.treasury_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid UNIQUE, kind text NOT NULL CHECK(kind IN ('online_rm','collection','expense','remittance')), amount numeric(16,2) NOT NULL CHECK(amount>0), currency text NOT NULL CHECK(currency IN ('TZS','KES')), category text NOT NULL, counterparty text NOT NULL, phone text NOT NULL DEFAULT '', reference text NOT NULL, transaction_date date NOT NULL DEFAULT CURRENT_DATE, notes text NOT NULL DEFAULT '', attachment_url text NOT NULL DEFAULT '', breakdown jsonb NOT NULL DEFAULT '{}', status text NOT NULL CHECK(status IN ('synced','pending_approval','approved')), created_by uuid NOT NULL, approved_by uuid, created_at timestamptz NOT NULL DEFAULT now(), CHECK(approved_by IS NULL OR approved_by<>created_by));
GRANT SELECT ON public.treasury_transactions TO authenticated; GRANT ALL ON public.treasury_transactions TO service_role;
ALTER TABLE public.treasury_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY ledger_read ON public.treasury_transactions FOR SELECT TO authenticated USING(public.has_permission('treasury_view'));
CREATE TABLE public.treasury_audit_flags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id uuid NOT NULL REFERENCES public.treasury_transactions(id), actor_id uuid NOT NULL, note text NOT NULL CHECK(length(trim(note))>=5), severity text NOT NULL CHECK(severity IN ('low','medium','high')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.treasury_audit_flags TO authenticated; GRANT ALL ON public.treasury_audit_flags TO service_role;
ALTER TABLE public.treasury_audit_flags ENABLE ROW LEVEL SECURITY;
CREATE POLICY flags_read ON public.treasury_audit_flags FOR SELECT TO authenticated USING(public.has_permission('audit_view'));
CREATE TABLE public.treasury_audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, transaction_id uuid NOT NULL REFERENCES public.treasury_transactions(id), action text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.treasury_audit_logs TO authenticated; GRANT ALL ON public.treasury_audit_logs TO service_role;
ALTER TABLE public.treasury_audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY treasury_logs_read ON public.treasury_audit_logs FOR SELECT TO authenticated USING(public.has_permission('audit_view'));
CREATE FUNCTION public.record_treasury_entry(p_kind text,p_amount numeric,p_currency text,p_category text,p_counterparty text,p_phone text,p_reference text,p_date date,p_notes text,p_attachment text,p_breakdown jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE entry_id uuid; entry_status text; BEGIN IF p_kind NOT IN ('collection','expense','remittance') OR NOT public.has_permission(CASE p_kind WHEN 'collection' THEN 'collection_record' WHEN 'expense' THEN 'expense_record' ELSE 'remittance_record' END) THEN RAISE EXCEPTION 'Access denied'; END IF; IF p_amount<=0 OR length(trim(p_counterparty))=0 OR length(trim(p_reference))=0 THEN RAISE EXCEPTION 'Amount, name and reference are required'; END IF; IF p_attachment<>'' AND p_attachment NOT LIKE 'https://%' THEN RAISE EXCEPTION 'Receipt URL must use HTTPS'; END IF; entry_status := CASE WHEN public.has_permission('treasury_approve') THEN 'approved' ELSE 'pending_approval' END; INSERT INTO public.treasury_transactions(kind,amount,currency,category,counterparty,phone,reference,transaction_date,notes,attachment_url,breakdown,status,created_by) VALUES(p_kind,p_amount,p_currency,p_category,p_counterparty,p_phone,p_reference,p_date,p_notes,p_attachment,p_breakdown,entry_status,auth.uid()) RETURNING id INTO entry_id; INSERT INTO public.treasury_audit_logs(actor_id,transaction_id,action,details) VALUES(auth.uid(),entry_id,'recorded',jsonb_build_object('status',entry_status)); RETURN entry_id; END $$;
REVOKE ALL ON FUNCTION public.record_treasury_entry(text,numeric,text,text,text,text,text,date,text,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.record_treasury_entry(text,numeric,text,text,text,text,text,date,text,text,jsonb) TO authenticated;
CREATE FUNCTION public.approve_treasury_entry(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE entry public.treasury_transactions; BEGIN IF NOT public.has_permission('treasury_approve') THEN RAISE EXCEPTION 'Access denied'; END IF; SELECT * INTO entry FROM public.treasury_transactions WHERE id=p_id FOR UPDATE; IF NOT FOUND OR entry.status<>'pending_approval' THEN RAISE EXCEPTION 'Entry is not pending'; END IF; IF entry.created_by=auth.uid() THEN RAISE EXCEPTION 'You cannot approve your own entry'; END IF; UPDATE public.treasury_transactions SET status='approved',approved_by=auth.uid() WHERE id=p_id; INSERT INTO public.treasury_audit_logs(actor_id,transaction_id,action) VALUES(auth.uid(),p_id,'approved'); END $$;
REVOKE ALL ON FUNCTION public.approve_treasury_entry(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.approve_treasury_entry(uuid) TO authenticated;
CREATE FUNCTION public.flag_treasury_entry(p_id uuid,p_note text,p_severity text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_permission('audit_flag') THEN RAISE EXCEPTION 'Access denied'; END IF; INSERT INTO public.treasury_audit_flags(transaction_id,actor_id,note,severity) VALUES(p_id,auth.uid(),p_note,p_severity); INSERT INTO public.treasury_audit_logs(actor_id,transaction_id,action,details) VALUES(auth.uid(),p_id,'flagged',jsonb_build_object('severity',p_severity)); END $$;
REVOKE ALL ON FUNCTION public.flag_treasury_entry(uuid,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.flag_treasury_entry(uuid,text,text) TO authenticated;
CREATE FUNCTION public.sync_completed_rm() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='completed' THEN INSERT INTO public.treasury_transactions(source_id,kind,amount,currency,category,counterparty,reference,transaction_date,status,created_by) VALUES(NEW.id,'online_rm',NEW.amount,NEW.currency,'Church Building/RM',NEW.contributor,NEW.reference,NEW.created_at::date,'synced',NEW.user_id) ON CONFLICT(source_id) DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER completed_rm_treasury AFTER INSERT OR UPDATE OF status ON public.rm_contributions FOR EACH ROW EXECUTE FUNCTION public.sync_completed_rm();